content.text:
{
  "name": "PQSC量子系统控制器",
  "name_en": "PQSC Programmable Quantum System Controller",
  "manufacturer": "Zurich Instruments",
  "description": "苏黎世仪器的PQSC是一种量子系统控制器，用于在量子测控实验中统一产生和分发触发信号，通过ZSync协调多台已连接仪器，并检查参考时钟锁定与端口连接状态。",
  "description_en": "The Zurich Instruments PQSC is a quantum system controller used in quantum measurement and control setups to generate and distribute triggers, coordinate multiple connected instruments over ZSync, and verify reference clock lock and port connectivity.",
  "actions": [
    {
      "action_name": "auto-arm",
      "description": "预置PQSC以进行触发，配置执行引擎并清空寄存器，可选设置触发次数和保持时间。",
      "description_en": "Arm the PQSC for triggering by configuring the execution engine and clearing registers, with optional trigger count and holdoff settings."
    },
    {
      "action_name": "auto-arm_and_run",
      "description": "预置PQSC并立即开始发送触发信号。",
      "description_en": "Arm the PQSC and immediately start sending trigger signals."
    },
    {
      "action_name": "auto-check_ref_clock",
      "description": "检查参考时钟是否已成功锁定。",
      "description_en": "Check whether the reference clock has locked successfully."
    },
    {
      "action_name": "auto-check_zsync_connection",
      "description": "检查指定ZSync端口上的连接是否已经建立。",
      "description_en": "Check whether the ZSync connection on the specified port or ports has been established."
    },
    {
      "action_name": "auto-find_zsync_worker_port",
      "description": "查找与指定设备相连的PQSC ZSync端口编号。",
      "description_en": "Find the PQSC ZSync port ID connected to a specified device."
    },
    {
      "action_name": "auto-run",
      "description": "开始通过ZSync向所有已连接仪器发送触发信号。",
      "description_en": "Start sending trigger signals to all connected instruments over ZSync."
    },
    {
      "action_name": "auto-stop",
      "description": "停止触发信号的生成与输出。",
      "description_en": "Stop trigger generation and output."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待触发生成和反馈处理完成。",
      "description_en": "Wait until trigger generation and feedback processing are complete."
    }
  ],
  "tag_hints": [
    "quantum control",
    "trigger generation",
    "ZSync synchronization",
    "multi-instrument coordination",
    "reference clock lock",
    "Zurich Instruments"
  ]
}

